const {DB,NETWORKS,packages,phone,ps,crypto}=require('./_core');
module.exports=async(req,res)=>{if(req.method!=='POST')return res.status(405).end();const {network,size_gb,email}=req.body||{},p=phone(req.body?.phone);if(!NETWORKS.includes(network))return res.status(400).json({error:'Unknown network'});if(!p)return res.status(400).json({error:'Enter a valid Ghana number, e.g. 0241234567'});try{const pkg=(await packages(network)).find(x=>x.size_gb===Number(size_gb));if(!pkg)return res.status(404).json({error:'That package is no longer available'});const reference='DB_'+Date.now()+'_'+crypto.randomBytes(5).toString('hex');await DB.create({reference,network,size_gb:pkg.size_gb,phone:p,price:pkg.price});const init=await ps('/transaction/initialize',{method:'POST',body:JSON.stringify({email:/^\S+@\S+\.\S+$/.test(email||'')?email:`${p}@example.com`,amount:Math.round(pkg.price*100),currency:'GHS',reference,metadata:{network,size_gb:pkg.size_gb,phone:p}})});if(!init.body.status) {await DB.update(reference,'failed',{error:'Paystack initialization failed'});return res.status(502).json({error:'Could not start payment'});}res.json({reference,access_code:init.body.data.access_code,price:pkg.price});}catch(e){res.status(502).json({error:'Could not create checkout. Verify database and provider configuration.'});}};
